     9→import Combine
    10→import Foundation
    11→import IntentsUI
    12→import MatrixRustSDK
    13→import UIKit
    14→
    15→class TimelineController: TimelineControllerProtocol {
    16→    private let roomProxy: JoinedRoomProxyProtocol
    17→    private let liveTimelineItemProvider: TimelineItemProviderProtocol
    18→    private let timelineItemFactory: RoomTimelineItemFactoryProtocol
    19→    private let mediaProvider: MediaProviderProtocol
    20→    private let appSettings: AppSettings
    21→    
    22→    let callbacks = PassthroughSubject<TimelineControllerCallback, Never>()
    23→    
    24→    private var activeTimeline: TimelineProxyProtocol
    25→    private var activeTimelineItemProvider: TimelineItemProviderProtocol {
    26→        didSet {
    27→            configureActiveTimelineItemProvider()
    28→        }
    29→    }
    30→    
    31→    private(set) var timelineItems = [RoomTimelineItemProtocol]()
    32→    
    33→    private(set) var paginationState: TimelinePaginationState = .initial {
    34→        didSet {
    35→            callbacks.send(.paginationState(paginationState))
    36→        }
    37→    }
    38→
    39→    var roomID: String {
    40→        roomProxy.id
    41→    }
    42→    
    43→    var timelineKind: TimelineKind {
    44→        activeTimelineItemProvider.kind
    45→    }
    46→    
    47→    init(roomProxy: JoinedRoomProxyProtocol,
    48→         timelineProxy: TimelineProxyProtocol,
    49→         initialFocussedEventID: String?,
    50→         timelineItemFactory: RoomTimelineItemFactoryProtocol,
    51→         mediaProvider: MediaProviderProtocol,
    52→         appSettings: AppSettings) {
    53→        self.roomProxy = roomProxy
    54→        liveTimelineItemProvider = timelineProxy.timelineItemProvider
    55→        self.timelineItemFactory = timelineItemFactory
    56→        self.mediaProvider = mediaProvider
    57→        self.appSettings = appSettings
    58→        
    59→        activeTimeline = timelineProxy
    60→        activeTimelineItemProvider = liveTimelineItemProvider
    61→        
    62→        guard let initialFocussedEventID else {
    63→            configureActiveTimelineItemProvider()
    64→            return
    65→        }
    66→        
    67→        Task {
    68→            paginationState = TimelinePaginationState(backward: .paginating, forward: .paginating)
    69→            
    70→            switch await focusOnEvent(initialFocussedEventID, timelineSize: 100) {
    71→            case .success:
    72→                break
    73→            case .failure:
    74→                // Setup the live timeline as a fallback.
    75→                configureActiveTimelineItemProvider()
    76→            }
    77→        }
    78→    }
    79→    
    80→    func focusOnEvent(_ eventID: String, timelineSize: UInt16) async -> Result<Void, TimelineControllerError> {
    81→        switch await roomProxy.timelineFocusedOnEvent(eventID: eventID, numberOfEvents: timelineSize) {
    82→        case .success(let timeline):
    83→            await timeline.subscribeForUpdates()
    84→            activeTimeline = timeline
    85→            activeTimelineItemProvider = timeline.timelineItemProvider
    86→            return .success(())
    87→        case .failure(let error):
    88→            if case .eventNotFound = error {
    89→                return .failure(.eventNotFound)
    90→            } else {
    91→                return .failure(.generic)
    92→            }
    93→        }
    94→    }
    95→    
    96→    func focusLive() {
    97→        activeTimeline = roomProxy.timeline
    98→        activeTimelineItemProvider = liveTimelineItemProvider
    99→    }
   100→    
   101→    func paginateBackwards(requestSize: UInt16) async -> Result<Void, TimelineControllerError> {
   102→        MXLog.info("Started back pagination request")
   103→        switch await activeTimeline.paginateBackwards(requestSize: requestSize) {
