   542→    func eventTimestamp(for itemID: TimelineItemIdentifier) -> Date? {
   543→        for itemProxy in activeTimelineItemProvider.itemProxies {
   544→            switch itemProxy {
   545→            case .event(let eventTimelineItemProxy):
   546→                if eventTimelineItemProxy.id == itemID {
   547→                    return eventTimelineItemProxy.timestamp
   548→                }
   549→            case .virtual:
   550→                break
   551→            case .unknown:
   552→                break
   553→            }
   554→        }
   555→        return nil
   556→    }
